from pathlib import Pathimport pandas as pdROOT = Path(__file__).resolve().parent.parentRESULTS = ROOT / "results"coverage = pd.read_csv(    RESULTS / "multisat_2024_recent_coverage.csv")behavior = pd.read_csv(    RESULTS / "multisat_2024_orbital_behavior.csv")# Three spacecraft in each altitude band.# Purposefully varied examples, not a random sample.selected_ids = [    59538, 48923, 58658,  # 200-350 km    43477, 56187, 45103,  # 350-500 km    58316, 59121, 46561,  # 500-650 km    42808, 42063, 54361,  # 650-800 km]cases = coverage[    coverage["norad_id"].isin(selected_ids)].copy()cases = cases.merge(    behavior[["norad_id", "behavior"]],    on="norad_id",    how="left",    validate="one_to_one")# Information requiring external verification.# Missing values are intentionally left blank.cases["mission_type_verified"] = pd.NAcases["operational_in_may_2024"] = pd.NAcases["mass_kg_verified"] = pd.NAcases["projected_area_m2_verified"] = pd.NAcases["propulsion_verified"] = pd.NAcases["specific_impulse_s_verified"] = pd.NAcases["cost_usd_verified"] = pd.NAcases["specification_source"] = pd.NAcases = cases.sort_values(    ["altitude_km", "norad_id"])output = RESULTS / "satellite_case_studies.csv"cases.to_csv(output, index=False)print("\nSELECTED SATELLITE CASE STUDIES:")print(    cases[        [            "norad_id",            "satellite_name",            "altitude_band",            "altitude_km",            "behavior",        ]    ].to_string(index=False))print(f"\nSelected {len(cases)} of 12 requested objects")print(f"Saved: {output}")